ALTER TABLE "USER" DROP CONSTRAINT IF EXISTS user_type_check;

-- squawk-ignore constraint-missing-not-valid, prefer-robust-stmts
ALTER TABLE "USER" ADD CONSTRAINT user_type_check
  CHECK ("TYPE" IN ('MANAGED', 'LDAP', 'OIDC', 'SAML', 'SERVICE'));

CREATE TABLE IF NOT EXISTS "SAML_GROUP" (
  "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY
, "UUID" UUID NOT NULL DEFAULT gen_random_uuid()
, "NAME" TEXT NOT NULL
, "CREATED_AT" TIMESTAMPTZ(3) NOT NULL DEFAULT now()
, CONSTRAINT "SAML_GROUP_PK" PRIMARY KEY ("ID")
, CONSTRAINT "SAML_GROUP_UUID_IDX" UNIQUE ("UUID")
, CONSTRAINT "SAML_GROUP_NAME_IDX" UNIQUE ("NAME")
, CONSTRAINT "SAML_GROUP_NAME_CHECK" CHECK (LENGTH("NAME") BETWEEN 1 AND 1024)
);

CREATE TABLE IF NOT EXISTS "SAML_GROUP_MAPPING" (
  "GROUP_ID" BIGINT NOT NULL
, "TEAM_ID" BIGINT NOT NULL
, CONSTRAINT "SAML_GROUP_MAPPING_PK" PRIMARY KEY ("GROUP_ID", "TEAM_ID")
, CONSTRAINT "SAML_GROUP_MAPPING_GROUP_FK" FOREIGN KEY ("GROUP_ID") REFERENCES "SAML_GROUP" ("ID") ON DELETE CASCADE
, CONSTRAINT "SAML_GROUP_MAPPING_TEAM_FK" FOREIGN KEY ("TEAM_ID") REFERENCES "TEAM" ("ID") ON DELETE CASCADE
);

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "SAML_GROUP_MAPPING_TEAM_IDX"
    ON "SAML_GROUP_MAPPING" ("TEAM_ID");

-- Authentication requests sent to the IdP, awaiting a response.
-- Deleted when the response arrives, which prevents replay.
CREATE TABLE IF NOT EXISTS "SAML_AUTHN_REQUEST" (
  "ID" TEXT NOT NULL
, "CODE_CHALLENGE" TEXT NOT NULL
, "REDIRECT_PATH" TEXT
, "EXPIRES_AT" TIMESTAMPTZ(3) NOT NULL
, CONSTRAINT "SAML_AUTHN_REQUEST_PK" PRIMARY KEY ("ID")
);

-- One-time codes that the frontend exchanges for a session token.
CREATE TABLE IF NOT EXISTS "SAML_LOGIN_CODE" (
  "CODE_HASH" TEXT NOT NULL
, "USER_ID" BIGINT NOT NULL
, "CODE_CHALLENGE" TEXT NOT NULL
, "EXPIRES_AT" TIMESTAMPTZ(3) NOT NULL
, CONSTRAINT "SAML_LOGIN_CODE_PK" PRIMARY KEY ("CODE_HASH")
, CONSTRAINT "SAML_LOGIN_CODE_USER_FK" FOREIGN KEY ("USER_ID") REFERENCES "USER" ("ID") ON DELETE CASCADE
);

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "SAML_LOGIN_CODE_USER_IDX"
    ON "SAML_LOGIN_CODE" ("USER_ID");
